public container getAttributeReferenceFromAll(RefRecId _instanceRecId)
{
    container attrRef = next getAttributeReferenceFromAll(_instanceRecId);

    GUPPriceTreeInstanceValue gupPriceTreeInstanceValue = GUPPriceTreeInstanceValue::find(_instanceRecId);
    GUPPricingSimulatorInstanceValue gupPricingSimulatorInstanceValue = GUPPricingSimulatorInstanceValue::find(_instanceRecId);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        if (gupPriceTreeInstanceValue.RecId)
        {
            RefTableId refTableId = tableNum(GUPPricingTree);
            RefRecId refRecId = GUPPricingTree::find(gupPriceTreeInstanceValue.PriceTreeName).RecId;
            attrRef = [refTableId, refRecId];
        }

        if (gupPricingSimulatorInstanceValue.RecId)
        {
            RefTableId refTableId = tableNum(RetailPricingSimulatorSalesTransaction);
            RefRecId refRecId = RetailPricingSimulatorSalesTransaction::find(gupPricingSimulatorInstanceValue.PricingSimulatorName).RecId;
            attrRef = [refTableId, refRecId];
        }
    }

    return attrRef;
}
